package cn.lili.modules.community.p0.stage3;
import cn.lili.cache.Cache;import cn.lili.common.properties.VerificationCodeProperties;import cn.lili.modules.verification.entity.dto.VerificationDTO;import cn.lili.modules.verification.entity.dos.VerificationSource;import cn.lili.modules.verification.entity.enums.VerificationEnums;import cn.lili.modules.verification.service.VerificationSourceService;import cn.lili.modules.verification.service.impl.VerificationServiceImpl;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.nio.file.*;import java.util.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Native captcha image generation only; it neither solves a login nor injects a Session. */
class Stage3CaptchaTest {
 @Test void newOwnedAssetsUseNativeGeneratorAndDoNotReturnTheAnswer()throws Exception{
  boolean stage45=System.getenv("S45_RUN")!=null;Path run=Path.of(Objects.requireNonNull(System.getenv(stage45?"S45_RUN":"S3_RUN"))).toRealPath();assertEquals(Path.of(stage45?"D:/git/daguanglu-p0-stage45/.stage45-runtime":"D:/git/daguanglu-p0-stage3/.stage3-runtime").toRealPath(),run.getParent());var manifest=object(Files.readString(run.resolve("evidence/captcha-assets.json")));assertEquals(run.getFileName().toString(),manifest.get("runId").getAsString());
  var images=new ArrayList<VerificationSource>();var sliders=new ArrayList<VerificationSource>();
  for(var raw:manifest.getAsJsonArray("assets")){var asset=raw.getAsJsonObject();var file=Path.of(asset.get("file").getAsString()).toRealPath();assertTrue(file.startsWith(run.resolve("private/captcha").toRealPath()));assertEquals(asset.get("sha256").getAsString(),digest(Files.readAllBytes(file)));var source=new VerificationSource();source.setId(asset.get("id").getAsString());source.setResource(file.toUri().toString());source.setType(asset.get("type").getAsString());if(source.getType().equals("RESOURCE"))images.add(source);else sliders.add(source);}
  assertEquals(3,images.size());assertEquals(2,sliders.size());var dto=new VerificationDTO();dto.setVerificationResources(images);dto.setVerificationSlider(sliders);var sources=mock(VerificationSourceService.class);when(sources.getVerificationCache()).thenReturn(dto);var cache=mock(Cache.class);var props=new VerificationCodeProperties();assertFalse(props.getLoginBypassEnabled());var service=new VerificationServiceImpl();ReflectionTestUtils.setField(service,"verificationSourceService",sources);ReflectionTestUtils.setField(service,"verificationCodeProperties",props);ReflectionTestUtils.setField(service,"cache",cache);
  var result=service.createVerification(VerificationEnums.LOGIN,"S3_UNIT_OWNED_CAPTCHA");assertFalse(result.containsKey("randomX"));assertTrue(String.valueOf(result.get("backImage")).startsWith("data:image/jpeg;base64,"));assertTrue(String.valueOf(result.get("slidingImage")).startsWith("data:image/png;base64,"));assertEquals(320,result.get("originalWidth"));assertEquals(48,result.get("sliderWidth"));for(String key:List.of("backImage","slidingImage")){byte[] bytes=Base64.getDecoder().decode(result.get(key).toString().split(",",2)[1]);assertTrue(bytes.length>100,"Native image must contain encoded bytes");var decoded=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes));assertNotNull(decoded,"Image must actually decode");assertEquals(key.equals("backImage")?320:48,decoded.getWidth());assertEquals(key.equals("backImage")?160:48,decoded.getHeight());}
 }
}